// Pick Tracker File — choose the exact file from the OneDrive search results.
// Stops with a clear message if the file is missing or the name matches more than one file.
// ONLY_WHEN_CHANGED: skip the run (no upsert, no report) when the file's version (eTag) is the same as
// the last successful scheduled run. Manual test runs always process the file.
const TRACKER_NAME = 'Trackers - NAM Distribution.xlsx';
const ONLY_WHEN_CHANGED = true;

// Microsoft Graph returns the search results as { value: [...] }; accept a plain list too
const found = $input.all().flatMap((i) => (Array.isArray(i.json.value) ? i.json.value : [i.json]));
const matches = found.filter((f) => f.file && f.name === TRACKER_NAME);
if (matches.length === 0) {
  throw new Error(`"${TRACKER_NAME}" was not found in your OneDrive. Check the file name in TRACKER_NAME ` +
    'and the search text on "Find Tracker".');
}
if (matches.length > 1) {
  const where = matches.map((f) => f.parentReference?.path ?? f.webUrl ?? f.id).join(' | ');
  throw new Error(`${matches.length} files are named "${TRACKER_NAME}": ${where}. Rename or move the extra copies.`);
}
const file = matches[0];

const memory = $getWorkflowStaticData('global');
if (ONLY_WHEN_CHANGED && memory.lastETag && memory.lastETag === file.eTag) {
  return []; // unchanged since the last run – nothing to do
}
return [{
  json: { id: file.id, name: file.name, eTag: file.eTag, lastModified: file.lastModifiedDateTime },
}];

// Clean Rows
// 1. COLUMNS = the exact column names in your n8n Data Table (only these are sent).
// 2. ALIASES = other headings the SharePoint tracker might use for the same column.
// 3. TYPES   = 'string' (default), 'number', 'numberText' (plain number stored as text, e.g. 1157.44)
//             or 'date' – match your Data Table column types
//             (the Column list in the Data Table node shows each type, e.g. "Invoice (number)").
//             'date' also turns Excel serial dates (e.g. 46118) into 2026-04-06.
// 4. KEY     = the column that identifies a row (matches existing rows so they are not duplicated).
const COLUMNS = ['Invoice', 'Value', 'Customer', 'Company_Code', 'Project_Manager', 'Name_the_PortalEmail_ID',
  'Received_Date', 'Allocated_Date', 'Invoice_Date'];
const ALIASES = {
  Invoice: ['invoice', 'invoice no', 'invoice number', 'invoice #', 'inv no'],
  Value: ['value', 'amount', 'invoice value'],
  Customer: ['customer', 'customer name', 'client'],
  Company_Code: ['company code', 'coco', 'co code', 'company_code'],
  Project_Manager: ['project manager', 'pm', 'manager'],
  Name_the_PortalEmail_ID: ['name the portal email id', 'portal email id', 'portal email', 'portal', 'email id',
    'submission portal'],
  Received_Date: ['received date', 'date received', 'received'],
  Allocated_Date: ['allocated date', 'date allocated', 'allocated'],
  Invoice_Date: ['invoice date', 'inv date'],
};
const TYPES = { Invoice: 'number', Value: 'numberText', Received_Date: 'date', Allocated_Date: 'date', Invoice_Date: 'date' };
const KEY = 'Invoice';
const UPPER = ['Customer', 'Company_Code']; // made upper case so spelling variants group together
// The tracker sometimes holds the sales org instead of the company code. Left = sales org, right = real company code.
const COMPANY_CODE_FIX = { G36C: 'G367', GS5C: 'G367' };

const norm = (s) => String(s ?? '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
const lookup = new Map();
for (const col of COLUMNS) {
  lookup.set(norm(col), col);
  for (const a of ALIASES[col] || []) lookup.set(norm(a), col);
}
// Excel serial day numbers (e.g. 46118 = 2026-04-06); the time of day is ignored
const fromSerial = (n) => (n >= 20000 && n <= 80000
  ? new Date(Date.UTC(1899, 11, 30) + Math.floor(n) * 86400000).toISOString().slice(0, 10) : null);
const pad = (n) => String(n).padStart(2, '0');
const convert = (col, v) => {
  if (v === '' || v == null) return null;
  if (TYPES[col] === 'number' || TYPES[col] === 'numberText') {
    if (typeof v === 'number') return Number.isFinite(v) ? (TYPES[col] === 'number' ? v : String(v)) : null;
    let t = String(v).trim().replace(/[\s,$€£]/g, '');
    const negative = /^\(.*\)$/.test(t) || t.startsWith('-'); // (1157.44) and -1157.44 are negative amounts
    t = t.replace(/^\((.*)\)$/, '$1').replace(/^-/, '');
    if (TYPES[col] === 'number') t = t.replace(/\.0+$/, '');
    // whole value must be a plain number: "7001 / 7002" or "INV-12" are not guessed
    if (!(TYPES[col] === 'number' ? /^\d+$/ : /^\d*\.?\d+$/).test(t)) return null;
    const n = Number(t) * (negative ? -1 : 1);
    return TYPES[col] === 'number' ? n : String(n);
  }
  if (TYPES[col] === 'date') {
    if (typeof v === 'number') return fromSerial(v);
    const t = String(v).trim();
    if (/^\d{5}(\.\d+)?$/.test(t)) return fromSerial(Number(t));
    const iso = t.match(/^(\d{4})-(\d{2})-(\d{2})/);
    if (iso) return `${iso[1]}-${iso[2]}-${iso[3]}`;
    const d = new Date(t); // e.g. 4/6/2026 (US order) or "Apr 6, 2026"
    return isNaN(d) ? null : `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
  }
  const text = String(v).replace(/\s+/g, ' ').trim();
  const out = UPPER.includes(col) ? text.toUpperCase() : text;
  return col === 'Company_Code' && COMPANY_CODE_FIX[out] ? COMPANY_CODE_FIX[out] : out;
};

// Stop early on the wrong file / wrong tab instead of saving nothing
const input = $input.all().filter((i) => Object.keys(i.json || {}).length);
if (!input.length) throw new Error('The uploaded sheet is empty. Check the file and the Sheet Name option on "Read Tracker Sheet". Nothing was changed.');
// Excel leaves empty cells out of a row, so collect the headings from every row
const headings = [...new Set(input.flatMap((i) => Object.keys(i.json)))];
if (!headings.some((h) => lookup.get(norm(h)) === KEY)) {
  throw new Error(`No "${KEY}" column found. Headings in the sheet: ${headings.join(', ')}. ` +
    'Check the file, the Sheet Name option on "Read Tracker Sheet", or add the heading to ALIASES. Nothing was changed.');
}

const rows = new Map();
for (const { json: raw } of input) {
  const row = {};
  for (const [header, value] of Object.entries(raw)) {
    const col = lookup.get(norm(header));
    if (col && row[col] == null) row[col] = convert(col, value);
  }
  if (row[KEY] == null || row[KEY] === '') continue; // blank / totals rows
  for (const col of COLUMNS) if (!(col in row)) row[col] = null;
  rows.set(String(row[KEY]), row); // a repeated key keeps the last row
}
return [...rows.values()].map((json) => ({ json }));

// Compare with Table — keep only invoices that are new or changed, so saving takes seconds, not minutes.
// If the table is empty, or more than BULK_LIMIT rows changed (e.g. the very first upload), ALL rows are passed on
// for a fast "clear table + bulk add" instead. Keep BULK_LIMIT the same as in the "Few changes?" step.
const BULK_LIMIT = 300;

const cleaned = $('Clean Rows').all().map((i) => i.json);
const columns = Object.keys(cleaned[0] || {});
const existing = new Map();
for (const { json: r } of $input.all()) {
  if (r.Invoice === undefined || r.Invoice === null || r.Invoice === '') continue; // empty table gives one empty item
  existing.set(String(r.Invoice), r);
}
const same = (a, b) => String(a ?? '').trim() === String(b ?? '').trim();
const changed = cleaned.filter((r) => {
  const before = existing.get(String(r.Invoice));
  return !before || columns.some((c) => !same(r[c], before[c]));
});
const rows = !existing.size || changed.length > BULK_LIMIT ? cleaned : changed;
return rows.map((json) => ({ json }));

// Summarise Upload — counts and data quality checks for the confirmation page.
// Fixed rules only (no clock, no randomness): the same file always gives the same result.
const KEY = 'Invoice';
const KEY_ALIASES = ['invoice', 'invoice no', 'invoice number', 'invoice #', 'inv no']; // keep in step with Clean Rows
const EARLIEST_DATE = '2020-01-01';
const DATE_COLUMNS = ['Received_Date', 'Allocated_Date', 'Invoice_Date'];
const LIST_LIMIT = 10;
const FILE_NAME = $('Pick Tracker File').first().json.name;

const norm = (s) => String(s ?? '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
const keyNames = new Set([KEY, ...KEY_ALIASES].map(norm));
const num = (v) => {
  const n = parseFloat(String(v ?? '').replace(/[^0-9.\-]/g, ''));
  return Number.isFinite(n) ? n : null;
};

// Raw sheet: blank-key rows and repeated invoices
const raw = $('Read Tracker Sheet').all().map((i) => i.json);
const seen = new Map();
const unreadable = []; // invoice cells that are not a plain number (e.g. "7001 / 7002"): skipped, not guessed
let blank = 0;
for (const r of raw) {
  const h = Object.keys(r).find((k) => keyNames.has(norm(k)));
  const id = h == null ? '' : String(r[h] ?? '').trim();
  if (!/\d/.test(id)) { blank++; continue; } // empty, or a label such as "Total"
  if (!/^\d+(\.0+)?$/.test(id.replace(/[\s,]/g, ''))) { unreadable.push(id); continue; }
  seen.set(id, (seen.get(id) || 0) + 1);
}
const duplicates = [...seen].filter(([, n]) => n > 1).map(([id]) => id).sort();

// Cleaned rows: quality checks
const rows = $('Clean Rows').all().map((i) => i.json);
const checks = {
  'missing value': (r) => num(r.Value) === null,
  'zero or negative value': (r) => num(r.Value) !== null && num(r.Value) <= 0,
  'missing customer': (r) => !r.Customer,
  'missing company code': (r) => !r.Company_Code,
  'no readable date': (r) => DATE_COLUMNS.every((c) => !r[c]),
  [`date before ${EARLIEST_DATE}`]: (r) => DATE_COLUMNS.some((c) => r[c] && r[c] < EARLIEST_DATE),
  'allocated before received': (r) => r.Allocated_Date && r.Received_Date && r.Allocated_Date < r.Received_Date,
};
const issues = {};
for (const [label, test] of Object.entries(checks)) {
  const ids = rows.filter(test).map((r) => String(r[KEY]));
  if (ids.length) issues[label] = { count: ids.length, examples: ids.slice(0, LIST_LIMIT) };
}

const fmt = (n) => n.toLocaleString('en-US');
// how many rows were actually written (only present when the "Compare with Table" step is used)
const written = (() => {
  try { return $('Compare with Table').all().filter((i) => i.json.Invoice !== undefined && i.json.Invoice !== null && i.json.Invoice !== '').length; }
  catch (e) { return null; }
})();
const parts = written === null
  ? [`${fmt(rows.length)} invoices saved from ${fmt(raw.length)} rows`]
  : [`${fmt(rows.length)} invoices in the file (${fmt(raw.length)} rows) · ${fmt(written)} new or changed rows saved, the rest were already up to date`];
if (blank) parts.push(`${fmt(blank)} blank or total rows skipped`);
if (unreadable.length) {
  parts.push(`${fmt(unreadable.length)} rows skipped because the invoice number is not a plain number: ` +
    unreadable.slice(0, LIST_LIMIT).join(', ') + (unreadable.length > LIST_LIMIT ? ', …' : ''));
}
if (duplicates.length) {
  parts.push(`${fmt(duplicates.length)} invoices appear more than once (last row kept): ` +
    duplicates.slice(0, LIST_LIMIT).join(', ') + (duplicates.length > LIST_LIMIT ? ', …' : ''));
}
for (const [label, { count, examples }] of Object.entries(issues)) {
  parts.push(`${fmt(count)} with ${label} (e.g. ${examples.slice(0, 3).join(', ')})`);
}
// SAP customer code / profit centre coverage (only when the "Add Lookups" step is used)
try {
  const looked = $('Add Lookups').all().map((i) => i.json);
  const pcRows = looked.filter((r) => ['3060', '3487', '3485'].includes(String(r.Company_Code)));
  parts.push(`SAP customer code found for ${fmt(looked.filter((r) => r.SAP_Customer_Code).length)} of ${fmt(looked.length)} invoices` +
    ` · profit centre found for ${fmt(pcRows.filter((r) => r.Profit_Center).length)} of ${fmt(pcRows.length)} (3060 / 3487 / 3485)`);
} catch (e) { /* step not in this workflow */ }
if (!duplicates.length && !unreadable.length && !Object.keys(issues).length) parts.push('no data quality issues found');

return [{
  json: {
    file: FILE_NAME,
    rowsRead: raw.length,
    rowsSaved: rows.length,
    blankRows: blank,
    unreadableInvoices: unreadable,
    duplicateInvoices: duplicates,
    issues,
    message: parts.join(' · '),
  },
}];

// Build Report — a simple, rule-based Production Tracker report as an HTML email.
// Fixed rules only: the same tracker file always produces the same report.
const RECIPIENTS = []; // e.g. ['name.surname@company.com', 'team@company.com']
const MONTHS_SHOWN = 12;
const TOP_CUSTOMERS = 10;
const DAYS_SHOWN = 14;
const DATE_ORDER = ['Received_Date', 'Allocated_Date', 'Invoice_Date']; // first filled date is used

if (!RECIPIENTS.length) throw new Error('Add at least one email address to RECIPIENTS at the top of "Build Report".');

const rows = $('Clean Rows').all().map((i) => i.json);
const quality = $('Summarise Upload').first().json;
const file = $('Pick Tracker File').first().json;

const num = (v) => {
  const n = parseFloat(String(v ?? '').replace(/[^0-9.\-]/g, ''));
  return Number.isFinite(n) ? n : 0;
};
const money = (n) => n.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const count = (n) => n.toLocaleString('en-US');
const pct = (part, whole) => (whole ? ((part / whole) * 100).toFixed(1) + '%' : '–');
const esc = (s) => String(s ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const dateOf = (r) => DATE_ORDER.map((c) => r[c]).find(Boolean) || null;

function group(keyOf) {
  const m = new Map();
  for (const r of rows) {
    const k = keyOf(r);
    if (!k) continue;
    const g = m.get(k) || { key: k, invoices: 0, value: 0 };
    g.invoices++;
    g.value += num(r.Value);
    m.set(k, g);
  }
  return [...m.values()];
}
const byValueThenKey = (a, b) => b.value - a.value || String(a.key).localeCompare(String(b.key));

const totalValue = rows.reduce((s, r) => s + num(r.Value), 0);
const months = group((r) => dateOf(r)?.slice(0, 7)).sort((a, b) => b.key.localeCompare(a.key)).slice(0, MONTHS_SHOWN);
const customers = group((r) => r.Customer || 'UNKNOWN CUSTOMER').sort(byValueThenKey);
const companies = group((r) => r.Company_Code || 'UNKNOWN COMPANY').sort(byValueThenKey);
const days = group((r) => dateOf(r)).sort((a, b) => b.key.localeCompare(a.key)).slice(0, DAYS_SHOWN);
const latestDate = days[0]?.key ?? '–';

const th = (align) => `style="text-align:${align};padding:6px 10px;background:#1f3a5f;color:#fff;font-weight:600"`;
const td = 'style="padding:5px 10px;border-bottom:1px solid #e5e7eb"';
const tdr = 'style="padding:5px 10px;border-bottom:1px solid #e5e7eb;text-align:right"';
function table(title, headers, data) {
  const head = headers.map((h, i) => `<th ${th(i ? 'right' : 'left')}>${esc(h)}</th>`).join('');
  const body = data.map((cells) => '<tr>' + cells.map((c, i) => `<td ${i ? tdr : td}>${esc(c)}</td>`).join('') + '</tr>').join('');
  return `<h3 style="margin:22px 0 8px;color:#1f3a5f">${esc(title)}</h3>` +
    `<table cellspacing="0" style="border-collapse:collapse;font-size:13px;min-width:420px">` +
    `<tr>${head}</tr>${body || `<tr><td ${td} colspan="${headers.length}">No data</td></tr>`}</table>`;
}
const kpi = (label, value) =>
  `<td style="padding:10px 18px;border:1px solid #e5e7eb"><div style="font-size:12px;color:#6b7280">${esc(label)}</div>` +
  `<div style="font-size:20px;font-weight:700;color:#111827">${esc(value)}</div></td>`;

const issueLines = [
  ...(quality.blankRows ? [`${count(quality.blankRows)} blank rows skipped`] : []),
  ...(quality.duplicateInvoices.length ? [`${count(quality.duplicateInvoices.length)} invoices appear more than once (last row kept)`] : []),
  ...Object.entries(quality.issues).map(([label, { count: n, examples }]) => `${count(n)} with ${label} (e.g. ${examples.slice(0, 3).join(', ')})`),
];

const html = `<div style="font-family:Segoe UI,Arial,sans-serif;color:#111827;max-width:900px">
<h2 style="margin:0 0 4px;color:#1f3a5f">Production Tracker Report</h2>
<div style="color:#6b7280;font-size:13px">Source: ${esc(file.name)} · file saved ${esc(String(file.lastModified ?? '').slice(0, 16).replace('T', ' '))} UTC · latest activity date ${esc(latestDate)}</div>
<table cellspacing="0" style="border-collapse:collapse;margin:16px 0"><tr>
${kpi('Invoices', count(rows.length))}${kpi('Total value', money(totalValue))}${kpi('Customers', count(customers.length))}${kpi('Company codes', count(companies.length))}
</tr></table>
${table(`Monthly summary (last ${MONTHS_SHOWN} months)`, ['Month', 'Invoices', 'Value'],
    months.map((g) => [g.key, count(g.invoices), money(g.value)]))}
${table(`Top ${TOP_CUSTOMERS} customers by value`, ['Customer', 'Invoices', 'Value', 'Share'],
    customers.slice(0, TOP_CUSTOMERS).map((g) => [g.key, count(g.invoices), money(g.value), pct(g.value, totalValue)]))}
${table('Company codes', ['Company code', 'Invoices', 'Value', 'Share'],
    companies.map((g) => [g.key, count(g.invoices), money(g.value), pct(g.value, totalValue)]))}
${table(`Daily activity (last ${DAYS_SHOWN} active days)`, ['Date', 'Invoices', 'Value'],
    days.map((g) => [g.key, count(g.invoices), money(g.value)]))}
<h3 style="margin:22px 0 8px;color:#1f3a5f">Data quality</h3>
<ul style="font-size:13px;margin:0;padding-left:18px">${issueLines.length ? issueLines.map((l) => `<li>${esc(l)}</li>`).join('') : '<li>No data quality issues found</li>'}</ul>
<p style="color:#9ca3af;font-size:11px;margin-top:24px">Generated automatically by n8n from the tracker file. Dates use ${DATE_ORDER.join(' → ')} (first filled).</p>
</div>`;

const subject = `Production Tracker Report – ${count(rows.length)} invoices · ${money(totalValue)} · as of ${latestDate}`;
return [{
  json: {
    subject,
    html,
    to: RECIPIENTS.join(', '), // for mail nodes with a plain "To" field (e.g. the company SMTP mail node)
    invoices: rows.length,
    totalValue,
    // Body for Microsoft Graph "send mail" (used by the Send Report step)
    mail: {
      message: {
        subject,
        body: { contentType: 'HTML', content: html },
        toRecipients: RECIPIENTS.map((address) => ({ emailAddress: { address } })),
      },
      saveToSentItems: true,
    },
  },
}];

// Remember Version — store the processed file's version so an unchanged file is skipped next time.
// n8n keeps this only for scheduled (published) runs, not manual test runs.
const memory = $getWorkflowStaticData('global');
memory.lastETag = $('Pick Tracker File').first().json.eTag;
return $input.all();
